CREATE TABLE "IncomingMapping" (
  "id" UUID NOT NULL,
  "type" TEXT NOT NULL,
  "cmsKey" TEXT NOT NULL,
  "cmsLabel" TEXT NOT NULL,
  "samoCode" TEXT NOT NULL,
  "samoName" TEXT NOT NULL,
  "adultCount" INTEGER,
  "childCount" INTEGER,
  "isActive" BOOLEAN NOT NULL DEFAULT true,
  "sortOrder" INTEGER NOT NULL DEFAULT 0,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "IncomingMapping_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "IncomingMapping_type_cmsKey_key" ON "IncomingMapping"("type", "cmsKey");
CREATE INDEX "IncomingMapping_type_isActive_idx" ON "IncomingMapping"("type", "isActive");
